#include <iostream>
#include <vector>

using namespace std;

struct Fenwick {
    int n;
    vector<int> tree;
    Fenwick(int n) : n(n), tree(n + 1, 0) {}
    void add(int i, int delta) {
        for (; i <= n; i += i & -i) tree[i] += delta;
    }
    int find_kth(int k) { // 0-based k-th available (i.e. prefix sum == k + 1)
        int idx = 0;
        for (int p = 1 << 20; p > 0; p >>= 1) {
            if (idx + p <= n && tree[idx + p] <= k) {
                idx += p;
                k -= tree[idx];
            }
        }
        return idx + 1;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    Fenwick bit(n);
    for (int i = 1; i <= n; ++i) {
        bit.add(i, 1);
    }

    vector<int> digits;
    long long rem = 1;

    for (int m = n; m >= 1; --m) {
        long long val = rem * m;
        long long q = val / k;
        long long r = val % k;
        if (r == 0) {
            digits.push_back((int)(q - 1));
            for (int rem_m = m - 1; rem_m >= 1; --rem_m) {
                digits.push_back(rem_m - 1);
            }
            break;
        } else {
            digits.push_back((int)q);
            rem = r;
        }
    }

    for (int d : digits) {
        int val = bit.find_kth(d);
        cout << val << "\n";
        bit.add(val, -1);
    }

    return 0;
}

