using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> a(n, vector<int>(m));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
        }
    }

    long long ans = 0;
    vector<long long> s(m);
    vector<int> b(m);
    vector<long long> pref(m + 1, 0);
    vector<int> l_bound(m), r_bound(m);
    vector<int> st(m);

    for (int u = 0; u < n; ++u) {
        for (int j = 0; j < m; ++j) {
            s[j] = 0;
            b[j] = 1e9;
        }
        for (int d = u; d < n; ++d) {
            for (int j = 0; j < m; ++j) {
                s[j] += a[d][j];
                b[j] = min(b[j], a[d][j]);
                pref[j + 1] = pref[j] + s[j];
            }

            // Monotonic stack for left bounds
            int top = 0;
            for (int j = 0; j < m; ++j) {
                while (top > 0 && b[st[top - 1]] >= b[j]) {
                    --top;
                }
                l_bound[j] = (top == 0 ? 0 : st[top - 1] + 1);
                st[top++] = j;
            }

            // Monotonic stack for right bounds
            top = 0;
            for (int j = m - 1; j >= 0; --j) {
                while (top > 0 && b[st[top - 1]] >= b[j]) {
                    --top;
                }
                r_bound[j] = (top == 0 ? m - 1 : st[top - 1] - 1);
                st[top++] = j;
            }

            for (int j = 0; j < m; ++j) {
                long long sum_r = pref[r_bound[j] + 1] - pref[l_bound[j]];
                long long cur = sum_r * b[j];
                if (cur > ans) ans = cur;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

