using namespace std;

bool query(int i, int j, int k) {
    cout << "? " << i << " " << j << " " << k << endl;
    string res;
    if (!(cin >> res) || res == "-1") exit(0);
    return res == "Yes";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    // Step 1: Find index of 1
    int one_idx = 1;
    for (int i = 2; i <= n; ++i) {
        if (!query(i, i, one_idx)) {
            one_idx = i;
        }
    }

    // Step 2: Compare elements using query(b, one_idx, a)
    // P_b + 1 > P_a <=> P_a < P_b
    auto comp = [&](int a, int b) {
        if (a == b) return false;
        return query(b, one_idx, a);
    };

    vector<int> a;
    for (int i = 1; i <= n; ++i) {
        if (i != one_idx) a.push_back(i);
    }

    vector<int> tmp(a.size());
    auto merge_sort = [&](auto self, int l, int r) -> void {
        if (r - l <= 1) return;
        int m = l + (r - l) / 2;
        self(self, l, m);
        self(self, m, r);
        int i = l, j = m, k = l;
        while (i < m && j < r) {
            if (comp(a[i], a[j])) {
                tmp[k++] = a[i++];
            } else {
                tmp[k++] = a[j++];
            }
        }
        while (i < m) tmp[k++] = a[i++];
        while (j < r) tmp[k++] = a[j++];
        for (int p = l; p < r; ++p) a[p] = tmp[p];
    };

    merge_sort(merge_sort, 0, (int)a.size());

    vector<int> ans(n + 1);
    ans[one_idx] = 1;
    for (size_t i = 0; i < a.size(); ++i) {
        ans[a[i]] = (int)(i + 2);
    }

    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << ans[i];
    }
    cout << endl;

    return 0;
}

