using namespace std;

bool check_person(int i, int n, const vector<long long>& x, const vector<long long>& d) {
    auto is_pos_good = [&](long long pos) {
        for (int j : {i - 1, i + 1}) {
            if (j >= 1 && j <= n) {
                if (x[j] - d[j] < pos && pos < x[j] + d[j]) {
                    return false;
                }
            }
        }
        return true;
    };

    return is_pos_good(x[i] - d[i]) || is_pos_good(x[i] + d[i]);
}

void solve() {
    int n;
    if (!(cin >> n)) return;

    vector<long long> a(n + 1), b(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];
    for (int i = 1; i <= n; ++i) cin >> b[i];

    vector<int> bad(n + 2, 0);
    int bad_count = 0;

    for (int i = 1; i <= n; ++i) {
        if (!check_person(i, n, a, b)) {
            bad[i] = 1;
            bad_count++;
        }
    }

    int q;
    cin >> q;
    while (q--) {
        int p;
        long long s;
        cin >> p >> s;
        b[p] = s;

        for (int i : {p - 1, p, p + 1}) {
            if (i >= 1 && i <= n) {
                if (bad[i]) {
                    bad_count--;
                    bad[i] = 0;
                }
                if (!check_person(i, n, a, b)) {
                    bad[i] = 1;
                    bad_count++;
                }
            }
        }

        if (bad_count == 0) {
            cout << "Yes\n";
        } else {
            cout << "No\n";
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

