const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

const int MAX_CELLS = 2600;
vector<long long> fact(MAX_CELLS), invFact(MAX_CELLS);

void precompute() {
    fact[0] = 1;
    invFact[0] = 1;
    for (int i = 1; i < MAX_CELLS; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    invFact[MAX_CELLS - 1] = modInverse(fact[MAX_CELLS - 1]);
    for (int i = MAX_CELLS - 2; i >= 1; --i) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    precompute();

    int n, m, b, w;
    if (!(cin >> n >> m >> b >> w)) return 0;

    vector<vector<long long>> f_b(n + 1, vector<long long>(m + 1, 0));
    vector<vector<long long>> f_w(n + 1, vector<long long>(m + 1, 0));

    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= m; ++c) {
            if (r * c < b && r * c < w) continue;
            long long val_b = 0;
            long long val_w = 0;
            for (int i = 0; i <= r; ++i) {
                int sign_i = (i % 2 == 1 ? -1 : 1);
                for (int j = 0; j <= c; ++j) {
                    int sign = (j % 2 == 1 ? -sign_i : sign_i);
                    int rem_cells = (r - i) * (c - j);
                    long long ways = nCr(r, i) * nCr(c, j) % MOD;
                    if (rem_cells >= b) {
                        long long term_b = ways * nCr(rem_cells, b) % MOD;
                        val_b = (val_b + sign * term_b) % MOD;
                    }
                    if (rem_cells >= w) {
                        long long term_w = ways * nCr(rem_cells, w) % MOD;
                        val_w = (val_w + sign * term_w) % MOD;
                    }
                }
            }
            f_b[r][c] = (val_b % MOD + MOD) % MOD;
            f_w[r][c] = (val_w % MOD + MOD) % MOD;
        }
    }

    long long ans = 0;
    for (int r1 = 1; r1 <= n; ++r1) {
        for (int r2 = 1; r2 <= n - r1; ++r2) {
            long long ways_r = nCr(n, r1) * nCr(n - r1, r2) % MOD;
            for (int c1 = 1; c1 <= m; ++c1) {
                if (f_b[r1][c1] == 0) continue;
                for (int c2 = 1; c2 <= m - c1; ++c2) {
                    if (f_w[r2][c2] == 0) continue;
                    long long ways_c = nCr(m, c1) * nCr(m - c1, c2) % MOD;
                    long long term = ways_r * ways_c % MOD;
                    term = term * f_b[r1][c1] % MOD;
                    term = term * f_w[r2][c2] % MOD;
                    ans = (ans + term) % MOD;
                }
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>

using namespace std;

inline long long floor_div(long long a, long long m) {
    long long res = a / m;
    long long rem = a % m;
    if (rem != 0 && ((a < 0) ^ (m < 0))) {
        res--;
    }
    return res;
}

inline long long floor_mod(long long a, long long m) {
    long long rem = a % m;
    if (rem < 0) rem += m;
    return rem;
}

long long floor_sum(long long n, long long m, long long a, long long b) {
    if (n == 0) return 0;
    long long a1 = floor_div(a, m);
    long long a2 = floor_mod(a, m);
    long long s = n * (n - 1) / 2 * a1;
    long long b1 = floor_div(b, m);
    long long b2 = floor_mod(b, m);
    if (a2 == 0) {
        return s + b1 * n;
    }
    long long k = (a2 * (n - 1) + b2) / m;
    return s + n * (k + b1) - floor_sum(k, a2, m, m + a2 - b2 - 1);
}

void solve() {
    long long n, m, a, b;
    if (!(cin >> n >> m >> a >> b)) return;
    long long ans = n - floor_sum(n, m, a, b) + floor_sum(n, m, a - 1, b - 1);
    cout << ans << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

