#include <iostream>
#include <vector>
#include <queue>

using namespace std;

const long long INF = 1e18;

struct State {
    long long d;
    int u;
    int c;
    bool operator>(const State& other) const {
        return d > other.d;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, k, l;
    if (!(cin >> n >> m >> k >> l)) return 0;

    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    vector<int> b(l);
    for (int i = 0; i < l; ++i) cin >> b[i];

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        long long c;
        cin >> u >> v >> c;
        adj[u].push_back({v, c});
        adj[v].push_back({u, c});
    }

    vector<long long> dist1(n + 1, INF), dist2(n + 1, INF);
    vector<int> c1(n + 1, -1), c2(n + 1, -1);

    priority_queue<State, vector<State>, greater<State>> pq;

    for (int u : b) {
        dist1[u] = 0;
        c1[u] = a[u];
        pq.push({0, u, a[u]});
    }

    while (!pq.empty()) {
        auto [d, u, c] = pq.top();
        pq.pop();

        if (c == c1[u] && d > dist1[u]) continue;
        if (c == c2[u] && d > dist2[u]) continue;
        if (c != c1[u] && c != c2[u]) continue;

        for (auto [v, w] : adj[u]) {
            long long nd = d + w;
            if (c == c1[v]) {
                if (nd < dist1[v]) {
                    dist1[v] = nd;
                    pq.push({nd, v, c});
                }
            } else if (c == c2[v]) {
                if (nd < dist2[v]) {
                    dist2[v] = nd;
                    pq.push({nd, v, c});
                }
            } else {
                if (nd < dist1[v]) {
                    dist2[v] = dist1[v];
                    c2[v] = c1[v];
                    dist1[v] = nd;
                    c1[v] = c;
                    pq.push({nd, v, c});
                } else if (nd < dist2[v]) {
                    dist2[v] = nd;
                    c2[v] = c;
                    pq.push({nd, v, c});
                }
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        long long ans = -1;
        if (c1[i] != -1 && c1[i] != a[i]) {
            ans = dist1[i];
        } else if (c2[i] != -1 && c2[i] != a[i]) {
            ans = dist2[i];
        }
        cout << ans << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n, m, d;
    if (!(cin >> n >> m >> d)) return 0;

    vector<long long> r(m + 1);
    for (int i = 0; i <= m; ++i) cin >> r[i];

    vector<long long> s(m);
    for (int i = 0; i < m; ++i) cin >> s[i];

    long long A = -(n * d) / 2;

    auto score_of = [&](long long x) -> long long {
        long long ax = llabs(x);
        if (ax <= r[1]) return s[0];
        if (ax > r[m]) return 0;
        int idx = lower_bound(r.begin(), r.end(), ax) - r.begin();
        return s[idx - 1];
    };

    vector<long long> diff(d + 1, 0);

    auto add_boundary = [&](long long B, long long delta) {
        long long rem = (B - A) % d;
        if (rem < 0) rem += d;
        long long j = (B - A - rem) / d;
        if (j >= 0 && j < n) {
            diff[rem] += delta;
        }
    };

    // Negative side: moving right from -r[i]-1 to -r[i] increases score
    for (int i = 1; i <= m; ++i) {
        long long prev_s = (i < m ? s[i] : 0);
        long long cur_s = s[i - 1];
        long long delta = cur_s - prev_s;
        add_boundary(-r[i], delta);
    }

    // Positive side: moving right from r[i] to r[i]+1 decreases score
    for (int i = 1; i <= m; ++i) {
        long long prev_s = s[i - 1];
        long long cur_s = (i < m ? s[i] : 0);
        long long delta = cur_s - prev_s;
        add_boundary(r[i] + 1, delta);
    }

    // Initial score at k = 0
    long long cur_score = 0;
    // Only arrows within [-r_M, r_M] have non-zero score
    // Arrow j is at A + j * D
    // -r_M <= A + j * D <= r_M
    long long min_j = max(0LL, (long long)ceil((-r[m] - A) / (double)d));
    long long max_j = min(n - 1, (long long)floor((r[m] - A) / (double)d));

    for (long long j = max(0LL, min_j - 2); j <= min(n - 1, max_j + 2); ++j) {
        long long pos = A + j * d;
        cur_score += score_of(pos);
    }

    long long best = cur_score;
    for (int k = 1; k < d; ++k) {
        cur_score += diff[k];
        if (cur_score > best) best = cur_score;
    }

    cout << best << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <tuple>
#include <cassert>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total += a[i];
    }

    if (total % n != 0) {
        cout << -1 << "\n";
        return 0;
    }

    long long target = total / n;
    vector<long long> d(n);
    for (int i = 0; i < n; ++i) {
        d[i] = a[i] - target;
    }

    int full = 1 << n;
    vector<int> dp(full, 0);
    vector<long long> sum_d(full, 0);

    for (int mask = 1; mask < full; ++mask) {
        int low = mask & -mask;
        int idx = __builtin_ctz(low);
        sum_d[mask] = sum_d[mask ^ low] + d[idx];

        int best = 0;
        for (int i = 0; i < n; ++i) {
            if ((mask >> i) & 1) {
                int val = dp[mask ^ (1 << i)];
                if (val > best) best = val;
            }
        }
        if (sum_d[mask] == 0) {
            dp[mask] = best + 1;
        } else {
            dp[mask] = best;
        }
    }

    vector<int> components;
    int rem = full - 1;

    while (rem > 0) {
        int low_bit = rem & -rem;
        int rest = rem ^ low_bit;
        bool found = false;

        // Iterate submasks of rest, and include low_bit
        for (int sub = rest; ; sub = (sub - 1) & rest) {
            int cand = sub | low_bit;
            if (sum_d[cand] == 0 && dp[rem ^ cand] == dp[rem] - 1) {
                components.push_back(cand);
                rem ^= cand;
                found = true;
                break;
            }
            if (sub == 0) break;
        }
        if (!found) {
            components.push_back(rem);
            break;
        }
    }

    vector<long long> cur_a = a;
    vector<tuple<int, int, long long>> ops;

    for (int comp : components) {
        vector<int> nodes;
        for (int i = 0; i < n; ++i) {
            if ((comp >> i) & 1) nodes.push_back(i);
        }
        if (nodes.size() <= 1) continue;
        int r = nodes[0];

        // 1: nodes with excess give to r
        for (size_t k = 1; k < nodes.size(); ++k) {
            int i = nodes[k];
            if (cur_a[i] > target) {
                long long z = cur_a[i] - target;
                ops.push_back({i + 1, r + 1, z});
                cur_a[i] -= z;
                cur_a[r] += z;
            }
        }

        // 2: r gives to nodes with deficit
        for (size_t k = 1; k < nodes.size(); ++k) {
            int j = nodes[k];
            if (cur_a[j] < target) {
                long long z = target - cur_a[j];
                ops.push_back({r + 1, j + 1, z});
                cur_a[r] -= z;
                cur_a[j] += z;
            }
        }
    }

    cout << ops.size() << "\n";
    for (auto [x, y, z] : ops) {
        cout << x << " " << y << " " << z << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, a, b, q;
    if (!(cin >> n >> a >> b >> q)) return 0;

    vector<int> queries(q);
    for (int i = 0; i < q; ++i) cin >> queries[i];

    // Precompute factorials up to n
    vector<int> fact(n + 1), invFact(n + 1), pow2(n + 1);
    fact[0] = 1;
    invFact[0] = 1;
    pow2[0] = 1;

    for (int i = 1; i <= n; ++i) {
        fact[i] = (1LL * fact[i - 1] * i) % MOD;
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }
    invFact[n] = modInverse(fact[n]);
    for (int i = n - 1; i >= 1; --i) {
        invFact[i] = (1LL * invFact[i + 1] * (i + 1)) % MOD;
    }

    auto nCr = [&](int n, int r) -> int {
        if (r < 0 || r > n) return 0;
        return 1LL * fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    };

    auto compute_F = [&](int coord) -> vector<int> {
        vector<int> F(n + 1, 0);

        long long cur_sum = (max(0, coord - n) <= 0 && 0 <= min(0, coord - 1)) ? 1 : 0;
        int cur_L = max(0, coord - n);
        int cur_R = min(0, coord - 1);

        F[n] = (cur_sum * pow2[n - 1]) % MOD;

        for (int m = 0; m < n - 1; ++m) {
            long long next_sum = (2LL * cur_sum - nCr(m, cur_R) + nCr(m, cur_L - 1)) % MOD;
            int next_L = max(0, coord - (n - (m + 1)));
            int next_R = min(m + 1, coord - 1);

            while (cur_L < next_L) {
                next_sum = (next_sum - nCr(m + 1, cur_L)) % MOD;
                cur_L++;
            }
            while (cur_L > next_L) {
                cur_L--;
                next_sum = (next_sum + nCr(m + 1, cur_L)) % MOD;
            }

            while (cur_R < next_R) {
                cur_R++;
                next_sum = (next_sum + nCr(m + 1, cur_R)) % MOD;
            }
            while (cur_R > next_R) {
                next_sum = (next_sum - nCr(m + 1, cur_R)) % MOD;
                cur_R--;
            }

            cur_sum = (next_sum % MOD + MOD) % MOD;
            int k = n - (m + 1);
            F[k] = (cur_sum * pow2[k - 1]) % MOD;
        }

        return F;
    };

    vector<int> Fa = compute_F(a);
    vector<int> Fb = compute_F(b);

    for (int k : queries) {
        long long leq_k = 1LL * Fa[k] * Fb[k] % MOD;
        long long leq_prev = (k > 1 ? 1LL * Fa[k - 1] * Fb[k - 1] % MOD : 0);
        long long exact_k = (leq_k - leq_prev + MOD) % MOD;
        cout << exact_k << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD = 998244353;
const int G = 3;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

void ntt(vector<long long>& a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        long long wlen = power(G, (MOD - 1) / len);
        if (invert) wlen = modInverse(wlen);
        for (int i = 0; i < n; i += len) {
            long long w = 1;
            for (int j = 0; j < len / 2; ++j) {
                long long u = a[i + j];
                long long v = (a[i + j + len / 2] * w) % MOD;
                a[i + j] = (u + v < MOD ? u + v : u + v - MOD);
                a[i + j + len / 2] = (u - v >= 0 ? u - v : u - v + MOD);
                w = (w * wlen) % MOD;
            }
        }
    }
    if (invert) {
        long long n_inv = modInverse(n);
        for (long long &x : a) x = (x * n_inv) % MOD;
    }
}

vector<long long> multiply(const vector<long long>& a, const vector<long long>& b) {
    int need = a.size() + b.size() - 1;
    int n = 1;
    while (n < need) n <<= 1;
    vector<long long> fa(a.begin(), a.end()), fb(b.begin(), b.end());
    fa.resize(n, 0);
    fb.resize(n, 0);
    ntt(fa, false);
    ntt(fb, false);
    for (int i = 0; i < n; ++i) fa[i] = (fa[i] * fb[i]) % MOD;
    ntt(fa, true);
    fa.resize(need);
    return fa;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s, t;
    if (!(cin >> s >> t)) return 0;

    int n = s.size();
    int m = t.size();

    // S_0: S[i] == '0'
    // S_1: S[i] == '1'
    // T_0_rev: T[m - 1 - j] == '0'
    // T_1_rev: T[m - 1 - j] == '1'
    vector<long long> s0(n), s1(n), t0_rev(m), t1_rev(m);
    for (int i = 0; i < n; ++i) {
        if (s[i] == '0') s0[i] = 1;
        else s1[i] = 1;
    }
    for (int j = 0; j < m; ++j) {
        if (t[m - 1 - j] == '0') t0_rev[j] = 1;
        else t1_rev[j] = 1;
    }

    // mismatch = (S[i+j] == 0 and T[j] == 1) + (S[i+j] == 1 and T[j] == 0)
    // conv1 = S_0 * T_1_rev
    // conv2 = S_1 * T_0_rev
    vector<long long> conv1 = multiply(s0, t1_rev);
    vector<long long> conv2 = multiply(s1, t0_rev);

    int ans = m;
    for (int i = 0; i <= n - m; ++i) {
        int idx = i + m - 1;
        int diff = conv1[idx] + conv2[idx];
        if (diff < ans) ans = diff;
    }

    cout << ans << "\n";
    return 0;
}
